 35	    private static void quickSort(int[] values, int fromIndex, int toIndex) {
 36	        while (toIndex - fromIndex > INSERTION_SORT_THRESHOLD) {
 37	            int pivotIndex = partition(values, fromIndex, toIndex, selectPivotIndex(values, fromIndex, toIndex));
 38	
 39	            if (pivotIndex - fromIndex < toIndex - (pivotIndex + 1)) {
 40	                quickSort(values, fromIndex, pivotIndex);
 41	                fromIndex = pivotIndex + 1;
 42	            } else {
 43	                quickSort(values, pivotIndex + 1, toIndex);
 44	                toIndex = pivotIndex;
 45	            }
 46	        }
 47	
 48	        insertionSort(values, fromIndex, toIndex);
 49	    }
