 51	    private static int partition(int[] values, int fromIndex, int toIndex, int pivotIndex) {
 52	        int lastIndex = toIndex - 1;
 53	        int pivot = values[pivotIndex];
 54	        int smallerElementBoundary = fromIndex;
 55	
 56	        swap(values, pivotIndex, lastIndex);
 57	
 58	        for (int currentIndex = fromIndex; currentIndex < lastIndex; currentIndex++) {
 59	            if (values[currentIndex] < pivot) {
 60	                swap(values, smallerElementBoundary, currentIndex);
 61	                smallerElementBoundary++;
 62	            }
 63	        }
 64	
 65	        swap(values, smallerElementBoundary, lastIndex);
 66	        return smallerElementBoundary;
 67	    }
