 69	    private static int selectPivotIndex(int[] values, int fromIndex, int toIndex) {
 70	        int lastIndex = toIndex - 1;
 71	        int middleIndex = fromIndex + ((toIndex - fromIndex) >>> 1);
 72	        return medianOfThreeIndex(values, fromIndex, middleIndex, lastIndex);
 73	    }
