 75	    private static int medianOfThreeIndex(int[] values, int firstIndex, int secondIndex, int thirdIndex) {
 76	        int firstValue = values[firstIndex];
 77	        int secondValue = values[secondIndex];
 78	        int thirdValue = values[thirdIndex];
 79	
 80	        if (firstValue < secondValue) {
 81	            if (secondValue < thirdValue) {
 82	                return secondIndex;
 83	            }
 84	
 85	            return firstValue < thirdValue ? thirdIndex : firstIndex;
 86	        }
 87	
 88	        if (firstValue < thirdValue) {
 89	            return firstIndex;
 90	        }
 91	
 92	        return secondValue < thirdValue ? thirdIndex : secondIndex;
 93	    }
