 95	    private static void insertionSort(int[] values, int fromIndex, int toIndex) {
 96	        for (int index = fromIndex + 1; index < toIndex; index++) {
 97	            int currentValue = values[index];
 98	            int insertionIndex = index - 1;
 99	
100	            while (insertionIndex >= fromIndex && values[insertionIndex] > currentValue) {
101	                values[insertionIndex + 1] = values[insertionIndex];
102	                insertionIndex--;
103	            }
104	
105	            values[insertionIndex + 1] = currentValue;
106	        }
107	    }
