109	    private static void swap(int[] values, int leftIndex, int rightIndex) {
110	        if (leftIndex == rightIndex) {
111	            return;
112	        }
113	
114	        int temporaryValue = values[leftIndex];
115	        values[leftIndex] = values[rightIndex];
116	        values[rightIndex] = temporaryValue;
117	    }
